type SituationRouteDestination = "focus" | "guide" | "redress" | "journal" | "search" | "community" | "sos";
type SituationRouteCard = {
  id: string;
  label: string;
  detail: string;
  meta: string;
  actionLabel: string;
  destination: SituationRouteDestination;
};

function getSituationRouteCards(issue: IssueGuide, identityLabel: string): SituationRouteCard[] {
  const issueLabel = issue.label.toLowerCase();
  const supportSummary =
    issue.supportPath.length > 0
      ? issue.supportPath
          .slice(0, 2)
          .map((path) => path.label)
          .join(" • ")
      : "Verified support";

  const cards: Record<SituationRouteDestination, SituationRouteCard> = {
    sos: {
      id: "sos",
      label: "If safety is dropping",
      detail: "Use SOS first. Keep the location ready and do not stay alone with a fast-moving emergency.",
      meta: issue.urgentNote,
      actionLabel: "Call SOS",
      destination: "sos"
    },
    focus: {
      id: "focus",
      label: "If the body is flooded",
      detail: `Use Reset to slow ${identityLabel.toLowerCase()} and make the next move smaller before anything else.`,
      meta: issue.steps[0],
      actionLabel: "Begin Reset",
      destination: "focus"
    },
    guide: {
      id: "guide",
      label: "If the facts need shaping",
      detail: `Open Path and turn ${issueLabel} into dates, names, evidence, and one clear next action.`,
      meta: issue.action,
      actionLabel: "Open Path",
      destination: "guide"
    },
    redress: {
      id: "redress",
      label: "If an office or person must answer",
      detail: "Open Help and keep the complaint route visible until the written path is ready.",
      meta: issue.followUp,
      actionLabel: "Open Help",
      destination: "redress"
    },
    journal: {
      id: "journal",
      label: "If you need to hold the thread",
      detail: "Save the mood, trigger, and what changed so the next step stays clear and easy to review.",
      meta: "Daily report and follow-up",
      actionLabel: "Open Journal",
      destination: "journal"
    },
    search: {
      id: "search",
      label: "If expert help should join",
      detail: "Open Explore for nearby counselor, psychologist, doctor, or official help matched to this issue.",
      meta: supportSummary,
      actionLabel: "Open Explore",
      destination: "search"
    },
    community: {
      id: "community",
      label: "If another person should stay in the loop",
      detail: "Use verified Messaging or a private room when you want another human to respond with care.",
      meta: "Verified-only support",
      actionLabel: "Open Messaging",
      destination: "community"
    }
  };

  const orderByIssue: Record<IssueId, SituationRouteDestination[]> = {
    general: ["guide", "journal", "search", "community", "redress", "focus", "sos"],
    anger: ["focus", "guide", "redress", "journal", "search", "community", "sos"],
    anxiety: ["focus", "journal", "search", "guide", "community", "redress", "sos"],
    fear: ["focus", "guide", "search", "journal", "community", "redress", "sos"],
    overconfidence: ["guide", "journal", "search", "focus", "community", "redress", "sos"],
    stigma: ["focus", "community", "journal", "search", "guide", "redress", "sos"],
    burnout: ["focus", "journal", "search", "guide", "community", "redress", "sos"],
    loneliness: ["community", "focus", "journal", "search", "guide", "redress", "sos"],
    grief: ["focus", "community", "journal", "search", "guide", "redress", "sos"],
    identity: ["guide", "journal", "search", "focus", "community", "redress", "sos"],
    health: ["guide", "focus", "journal", "search", "community", "redress", "sos"],
    financial: ["guide", "journal", "search", "focus", "community", "redress", "sos"],
    relationship: ["guide", "focus", "journal", "community", "search", "redress", "sos"],
    parenting: ["guide", "community", "journal", "focus", "search", "redress", "sos"],
    trauma: ["focus", "guide", "journal", "community", "search", "redress", "sos"],
    academic: ["focus", "guide", "journal", "search", "community", "redress", "sos"],
    addiction: ["guide", "focus", "community", "journal", "search", "redress", "sos"],
  };

  return orderByIssue[issue.id].map((destination) => cards[destination]);
}

function getAdaptiveBeaconXModes(issueId: IssueId) {
  // Each dimension gets wisdom modes matched to what it needs most
  const labels: string[] =
    issueId === "anger" || issueId === "fear" || issueId === "overconfidence"
      ? ["Guru Granth Sahib", "Krishna", "Stoic", "Jain", "Science", "Action"]
    : issueId === "anxiety" || issueId === "burnout" || issueId === "academic"
      ? ["Guru Granth Sahib", "Buddha", "Science", "Krishna", "Resolve", "Action"]
    : issueId === "stigma" || issueId === "loneliness" || issueId === "identity"
      ? ["Guru Granth Sahib", "Buddha", "Bible", "Jain", "Resolve", "Action"]
    : issueId === "grief"
      ? ["Guru Granth Sahib", "Bible", "Quran", "Buddha", "Science", "Resolve"]
    : issueId === "trauma"
      ? ["Guru Granth Sahib", "Buddha", "Science", "Bible", "Resolve", "Action"]
    : issueId === "relationship"
      ? ["Guru Granth Sahib", "Krishna", "Bible", "Jain", "Resolve", "Action"]
    : issueId === "parenting"
      ? ["Guru Granth Sahib", "Bible", "Krishna", "Science", "Resolve", "Action"]
    : issueId === "health"
      ? ["Science", "Guru Granth Sahib", "Buddha", "Quran", "Resolve", "Action"]
    : issueId === "financial"
      ? ["Stoic", "Guru Granth Sahib", "Quran", "Science", "Resolve", "Action"]
    : issueId === "addiction"
      ? ["Guru Granth Sahib", "Buddha", "Science", "Bible", "Resolve", "Action"]
    : ["Universal Beacon", "Guru Granth Sahib", "Krishna", "Buddha", "Science", "Resolve", "Action"];

  return beaconXWisdomModes.filter((mode) => labels.includes(mode.label));
}

