let relaxingToneSoundInstance: AudioPlayer | null = null;
let relaxingToneSoundLoadPromise: Promise<AudioPlayer> | null = null;

async function ensureRelaxingToneSoundLoaded() {
  if (Platform.OS === "web") return null;
  if (relaxingToneSoundInstance) {
    return relaxingToneSoundInstance;
  }
  if (!relaxingToneSoundLoadPromise) {
    relaxingToneSoundLoadPromise = Promise.resolve(
      createAudioPlayer(require("./assets/calm-tone-beep.wav"), {
        downloadFirst: true
      })
    )
      .then((sound) => {
        relaxingToneSoundInstance = sound;
        return sound;
      })
      .catch((error) => {
        relaxingToneSoundLoadPromise = null;
        throw error;
      });
  }
  return relaxingToneSoundLoadPromise;
}

async function releaseRelaxingToneSound() {
  const sound = relaxingToneSoundInstance;
  relaxingToneSoundInstance = null;
  relaxingToneSoundLoadPromise = null;
  if (sound) {
    try {
      sound.remove();
    } catch {
      // Ignore unload failures during cleanup.
    }
  }
}

function isPlayChallengeId(value: string): value is PlayChallengeId {
  return (
    value === "reset" ||
    value === "focus" ||
    value === "move" ||
    value === "connect" ||
    value === "reflect"
  );
}

function isCommunityTopicFilterId(value: string): value is CommunityTopicFilterId {
  return (
    value === "all" ||
    value === "general" ||
    value === "student" ||
    value === "care" ||
    value === "work" ||
    value === "complaint" ||
    value === "support" ||
    value === "grief" ||
    value === "trauma" ||
    value === "addiction" ||
    value === "relationships" ||
    value === "financial" ||
    value === "parenting" ||
    value === "identity" ||
    value === "anger" ||
    value === "anxiety" ||
    value === "burnout" ||
    value === "loneliness" ||
    value === "health" ||
    value === "academic"
  );
}

function getMeditationStartChakra(issueId: IssueId): ChakraId {
  if (issueId === "general") return "thirdEye";
  if (issueId === "anxiety" || issueId === "fear" || issueId === "burnout" || issueId === "financial" || issueId === "trauma") return "root";
  if (issueId === "anger" || issueId === "overconfidence" || issueId === "health" || issueId === "academic") return "solar";
  if (issueId === "loneliness" || issueId === "grief" || issueId === "relationship" || issueId === "parenting") return "heart";
  if (issueId === "stigma" || issueId === "addiction") return "throat";
  if (issueId === "identity") return "crown";
  return "thirdEye";
}

function getMeditationTone(chakraId: ChakraId) {
  const toneIdByChakra: Record<ChakraId, RelaxingToneMode["id"]> = {
    root: "bilateral-soft-1",
    sacral: "bilateral-soft-2",
    solar: "binaural-alpha-6",
    heart: "binaural-alpha-7",
    throat: "iso-6",
    thirdEye: "binaural-theta-4",
    crown: "reset-quiet"
  };
  const toneId = toneIdByChakra[chakraId];
  return mindRelaxingToneModes.find((tone) => tone.id === toneId) ?? mindRelaxingToneModes[0];
}

function buildMeditationVideoUrl(chakra: MeditationChakra) {
  return `https://www.youtube.com/results?search_query=${encodeURIComponent(
    `${chakra.label} guided meditation`
  )}`;
}

