  async function clearIssueReminder() {
    if (!notificationsAvailable) {
      setIssueReminderId(null);
      setIssueReminderMode(null);
      setIssueReminderIssueId(null);
      return;
    }

    if (issueReminderId) {
      await Notifications.cancelScheduledNotificationAsync(issueReminderId).catch(() => undefined);
    }
    setIssueReminderId(null);
    setIssueReminderMode(null);
    setIssueReminderIssueId(null);
  }

  async function clearRetentionReminder() {
    if (!notificationsAvailable) {
      setRetentionReminderId(null);
      setRetentionReminderIssueId(null);
      return;
    }

    if (retentionReminderId) {
      await Notifications.cancelScheduledNotificationAsync(retentionReminderId).catch(() => undefined);
    }
    setRetentionReminderId(null);
    setRetentionReminderIssueId(null);
  }

  async function scheduleRetentionReminder(reason: "check-in" | "intake") {
    if (!notificationsAvailable) {
      return;
    }

    if (!reminderEnabled && followUpMode === "off") {
      return;
    }

    const currentPermissions = await Notifications.getPermissionsAsync().catch(() => null);
    let granted = currentPermissions?.granted ?? false;

    if (!granted) {
      const requestedPermissions = currentPermissions?.canAskAgain
        ? await Notifications.requestPermissionsAsync().catch(() => null)
        : currentPermissions;
      granted = requestedPermissions?.granted ?? false;
      if (!granted) {
        Alert.alert("Retention alert", "Enable notifications to keep the follow-up loop alive.");
        return;
      }
    }

    await clearRetentionReminder();

    const triggerDate = new Date(Date.now() + 26 * 60 * 60 * 1000);
    const body =
      reason === "check-in"
        ? `${selectedIssueGuide.label}: ${selectedIssueGuide.action} Then open Path and add one line about what changed.`
        : `${selectedIssueGuide.label}: you shared the full intake. ${selectedIssueGuide.followUp} Open Path or Journal and continue the follow-up.`;
    const identifier = await Notifications.scheduleNotificationAsync({
      content: {
        title: "Aethon Beacon retention check-in",
        body,
        data: { tab: "today" },
        ...(Platform.OS === "android" ? { channelId: "aethon-reminders" } : {})
      },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.DATE,
        date: triggerDate
      }
    }).catch(() => null);

    if (!identifier) {
      return;
    }

    setRetentionReminderId(identifier);
    setRetentionReminderIssueId(selectedIssueGuide.id);
  }

  async function scheduleIssueReminder(mode: IssueReminderMode, issueOverride?: IssueId) {
    if (!notificationsAvailable) {
      Alert.alert("Path reminder", "Path reminders are not available in this browser.");
      return;
    }
    const reminderIssue =
      issueOverride !== undefined
        ? issueGuides.find((guide) => guide.id === issueOverride) ?? selectedIssueGuide
        : selectedIssueGuide;

    const currentPermissions = await Notifications.getPermissionsAsync().catch(() => null);
    let granted = currentPermissions?.granted ?? false;

    if (!granted) {
      const requestedPermissions = currentPermissions?.canAskAgain
        ? await Notifications.requestPermissionsAsync().catch(() => null)
        : currentPermissions;
      granted = requestedPermissions?.granted ?? false;
      if (!granted) {
        Alert.alert(
          "Path reminder",
          "Enable notifications to schedule issue follow-up reminders."
        );
        return;
      }
    }

    await clearIssueReminder();

    const delayMs = mode === "tomorrow" ? 24 * 60 * 60 * 1000 : 7 * 24 * 60 * 60 * 1000;
    const triggerDate = new Date(Date.now() + delayMs);
    const identifier = await Notifications.scheduleNotificationAsync({
      content: {
        title: "Aethon Beacon follow-up",
        body: `${reminderIssue.label}: open Path and continue the next step.`,
        data: { tab: "today" },
        ...(Platform.OS === "android" ? { channelId: "aethon-reminders" } : {})
      },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.DATE,
        date: triggerDate
      }
    }).catch(() => null);

    if (!identifier) {
      Alert.alert("Path reminder", "Could not schedule the follow-up reminder.");
      return;
    }

    setIssueReminderId(identifier);
    setIssueReminderMode(mode);
    setIssueReminderIssueId(reminderIssue.id);
    Alert.alert(
      "Path reminder",
      mode === "tomorrow"
        ? "A follow-up reminder is set for tomorrow."
        : "A follow-up reminder is set for next week."
    );
  }

  async function previewRetentionAlert() {
    if (!notificationsAvailable) {
      Alert.alert(
        "Retention alert",
        "This browser can show the alert preview, but it cannot schedule a real notification."
      );
      return;
    }

    const currentPermissions = await Notifications.getPermissionsAsync().catch(() => null);
    let granted = currentPermissions?.granted ?? false;

    if (!granted) {
      const requestedPermissions = currentPermissions?.canAskAgain
        ? await Notifications.requestPermissionsAsync().catch(() => null)
        : currentPermissions;
      granted = requestedPermissions?.granted ?? false;
      if (!granted) {
        Alert.alert(
          "Retention alert",
          "Enable notifications first if you want this test alert to leave the app."
        );
        return;
      }
    }

    const now = new Date(Date.now() + 5000);
    const scheduled = await Notifications.scheduleNotificationAsync({
      content: {
        title: "Aethon Beacon emotional check-in",
        body: getReminderBody(reminderMode, selectedIssueGuide, profileDisplayName),
        ...(Platform.OS === "android" ? { channelId: "aethon-reminders" } : {})
      },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.DATE,
        date: now
      }
    }).catch(() => null);

    Alert.alert(
      "Retention alert",
      scheduled
        ? "A test notification was scheduled for a few seconds from now."
        : "The app could not schedule the test notification, but the retention alert path is set up."
    );
  }

