  function submitUserReview(): boolean {
    const text = reviewDraft.trim();
    const safetyViolation = inspectCommunitySafety(text);
    if (safetyViolation) {
      safetyAlertMessage(safetyViolation.message);
      return false;
    }
    const reviewText =
      text.length > 0
        ? text
        : `Quick rating only. Exit review rating: ${Math.min(5, Math.max(1, Math.round(reviewRating)))}/5.`;
    const review: UserReview = {
      id: `review-${Date.now()}-${Math.floor(Math.random() * 100000)}`,
      createdAt: new Date().toISOString(),
      rating: Math.min(5, Math.max(1, Math.round(reviewRating))),
      text: reviewText,
      contact: reviewContact.trim().slice(0, 120),
      roleId: profileRoleId,
      platform: Platform.OS
    };
    setUserReviews((current) => [review, ...current].slice(0, 50));
    setReviewDraft("");
    Alert.alert("User review", "Thank you. Your review is saved for launch improvement.");
    return true;
  }

  function openGuidedAction(action: GuidedAction) {
    if (action === "profile") {
      openProfileAccessPanel();
      return;
    }
    if (action === "sos") {
      handleEmergencyCall();
      return;
    }
    handleTabPress(action);
  }

  function handleTabPress(tabId: TabId, options?: { recordHistory?: boolean }) {
    setShowSectionSwitcher(false);
    if (tabId !== activeTab && options?.recordHistory !== false) {
      setTabHistory((current) => {
        const next = current.filter((item) => item !== tabId);
        return [...next, activeTab].slice(-10);
      });
    }
    if (tabId === "today") {
      setPendingTabFocusAnchor(needsPresentMoodCheck ? { tab: "today", key: "today:presentMood" } : null);
    } else {
      setPendingTabFocusAnchor(null);
    }
    if (tabId === "language") {
      setLanguagePageNonce((current) => current + 1);
    }
    // Track Vedic view date for daily badge reset
    if (tabId === "vedic") {
      const today = new Date().toISOString().slice(0, 10);
      setLastVedicViewDate(today);
    }
    // Log tab visit for exit report
    const tabLabelMap: Partial<Record<TabId, string>> = {
      today: "Today", journal: "Journal", vedic: "Vedic / Horoscope",
      guide: "Guidance", community: "Community", tones: "Tones",
      meditation: "Meditation", settings: "Settings", focus: "Calm Focus",
      play: "Practice", insights: "Insights", search: "Search",
    };
    logSessionEvent({ type: "tab_visit", label: tabLabelMap[tabId] ?? tabId, ts: Date.now() });
    setActiveTab(tabId);
    scrollTabSurfaceToTop();
  }

  function handleNextTab() {
    const nextTabs = visibleTabs.map((tab) => tab.id);
    if (nextTabs.length === 0) return;
    const currentIndex = nextTabs.indexOf(activeTab);
    const nextIndex = currentIndex >= 0 ? (currentIndex + 1) % nextTabs.length : 0;
    handleTabPress(nextTabs[nextIndex], { recordHistory: false });
  }

  function goBackOneTab() {
    const previousTab = tabHistory[tabHistory.length - 1];
    if (!previousTab) {
      handleTabPress("today", { recordHistory: false });
      return;
    }
    setTabHistory((current) => current.slice(0, -1));
    handleTabPress(previousTab, { recordHistory: false });
  }

  function enterMainFlow() {
    setShowExitReviewPrompt(false);
    setShowOnboardingPanel(false);
    setHasSeenExitReviewPrompt(true);
    handleTabPress("today");
  }

  function openProfileAccessPanel(showVerificationSection = false) {
    setShowExitReviewPrompt(false);
    setHasSeenExitReviewPrompt(true);
    setShowOnboardingPanel(false);
    setShowSectionSwitcher(false);
    setShowAccessVerificationSection(showVerificationSection);
    setShowAccessPanel(true);
  }

  function exitToStart() {
    setShowSectionSwitcher(false);
    // Only show exit review at genuine end of session — after user submitted an issue, once per session
    if (hasSubmittedIssue && !hasSeenExitReviewPrompt) {
      setShowExitReviewPrompt(true);
    } else {
      setShowExitReviewPrompt(false);
    }
    setShowOnboardingPanel(true);
    scrollViewRef.current?.scrollTo({ y: 0, animated: false });
    if (Platform.OS === "web") {
      window.scrollTo(0, 0);
    }
  }

  function captureSectionLayout(tabId: TabId) {
    return (event: { nativeEvent: { layout: { y: number } } }) => {
      const nextY = event.nativeEvent.layout.y;
      setSectionOffsets((current) =>
        current[tabId] === nextY ? current : { ...current, [tabId]: nextY }
      );
    };
  }

  function captureFocusLayout(anchorKey: string) {
    return (event: { nativeEvent: { layout: { y: number } } }) => {
      const nextY = event.nativeEvent.layout.y;
      setFocusOffsets((current) => (current[anchorKey] === nextY ? current : { ...current, [anchorKey]: nextY }));
    };
  }

  function scrollTabSurfaceToTop() {
    const forceTop = () => {
      scrollViewRef.current?.scrollTo({ y: 0, animated: false });
      if (Platform.OS === "web" && typeof window !== "undefined") {
        try {
          window.history.scrollRestoration = "manual";
        } catch {
          // Some browsers block manual restoration; fall back to explicit scrolling below.
        }
        window.scrollTo(0, 0);
        const root = document.documentElement;
        const body = document.body;
        if (root) root.scrollTop = 0;
        if (body) body.scrollTop = 0;
      }
    };

    forceTop();
    if (Platform.OS === "web" && typeof window !== "undefined") {
      requestAnimationFrame(forceTop);
      requestAnimationFrame(() => requestAnimationFrame(forceTop));
      setTimeout(forceTop, 0);
      setTimeout(forceTop, 80);
    }
  }

  function showRouteNotice(title: string, detail: string) {
    if (routeNoticeTimerRef.current !== null) {
      clearTimeout(routeNoticeTimerRef.current);
    }
    setRouteNotice({ title, detail });
    routeNoticeTimerRef.current = setTimeout(() => {
      setRouteNotice(null);
      routeNoticeTimerRef.current = null;
    }, 4200);
  }

  function routeAfterPrivateIntake(nextRoute: PendingPrivateIntakeRoute | null) {
    if (!nextRoute) {
      handleTabPress("guide");
      return;
    }

    if (nextRoute.routeTab === "redress") {
      openRedressTab(nextRoute.redressRouteId);
      return;
    }

    openGuideTab(nextRoute.issueId);
  }

  function completePrivateIntake() {
    setPrivateIntakeSavedAt(new Date().toISOString());
    const intakeReport = buildPrivateIntakeReport(
      privateIntakeDraft,
      profileDisplayName,
      selectedIssueGuide,
      pendingPrivateIntakeRoute?.routeTab ?? "guide"
    );
    setVisitReports((current) => [
      {
        id: `intake-${Date.now()}`,
        createdAt: new Date().toISOString(),
        kind: "daily" as VisitReportKind,
        title: `Private intake report / ${profileDisplayName}`,
        summary: intakeReport.summary,
        emotional: intakeReport.emotionalRead,
        practical: intakeReport.practicalRead,
        social: intakeReport.socialRead,
        safety: intakeReport.safetyRead,
        nextStep: intakeReport.nextStep,
        routeLabel: intakeReport.recommendedRoute,
        identityLabel: profileDisplayName,
        issueLabel: selectedIssueGuide.label,
        entryCount: 0,
        sourceLabel: "Private intake"
      },
      ...current
    ].slice(0, 40));
    void scheduleRetentionReminder("intake");
    const nextRoute = pendingPrivateIntakeRoute;
    setPendingPrivateIntakeRoute(null);
    setShowPrivateIntakePanel(false);
    showRouteNotice(
      "Private intake saved",
      "Thanks for trusting me with the context. I’m opening the next step now."
    );
    routeAfterPrivateIntake(nextRoute);
  }

  function openGuideTab(issueId: IssueId) {
    setIssueGuideId(issueId);
    setPendingTabFocusAnchor({ tab: "guide", key: `guide:${issueId}` });
    handleTabPress("guide");
    scrollTabSurfaceToTop();
    const issue = issueGuides.find((guide) => guide.id === issueId) ?? selectedIssueGuide;
    showRouteNotice("Path opened", `${issue.label}: one clear next step is ready.`);
  }

  function openRedressTab(routeId: RedressRouteId) {
    setRedressRouteId(routeId);
    setPendingTabFocusAnchor({ tab: "redress", key: `redress:${routeId}` });
    handleTabPress("redress");
    scrollTabSurfaceToTop();
    const route = redressRoutes.find((item) => item.id === routeId) ?? selectedRedressRoute;
    showRouteNotice("Help opened", `${route.label}: the redress path is ready.`);
  }

  function openRouteDecision(
    rawText: string,
    issue: IssueGuide,
    route: AIHelpRoute,
    redressRouteId: RedressRouteId,
    identityLabel: string
  ) {
    const routeLabel =
      route === "redress" || route === "urgent"
        ? "Help route"
        : route === "professional"
          ? "Guidance route"
          : issue.label;
    const issueDisplayLabel = issue.id === "anxiety" ? "Calm route" : issue.label;
    setPendingRouteDecision({
      rawText,
      issueId: issue.id,
      issueLabel: issueDisplayLabel,
      identityLabel,
      route,
      redressRouteId
    });
    showRouteNotice("Choose next step", "Pick the route that fits best before the app moves forward.");
  }

  function getRouteChoiceLabel(choice: RouteChoiceId) {
    if (choice === "sos") return "SOS";
    if (choice === "help") return "Help";
    if (choice === "path") return "Path";
    if (choice === "reset") return "Reset";
    if (choice === "search") return "Search";
    return "Journal";
  }

  function writeRouteFollowUpReport(followUp: ActiveRouteFollowUp, status: RouteFollowUpStatus) {
    const statusLabel =
      status === "resolved"
        ? "Resolved"
        : status === "more-guidance"
          ? "Needs more guidance"
          : status === "reminder-set"
            ? "Reminder set"
            : "Open";

    setVisitReports((current) => [
      {
        id: `follow-up-${Date.now()}`,
        createdAt: new Date().toISOString(),
        kind: "step" as VisitReportKind,
        title: `Follow-up / ${followUp.choiceLabel}`,
        summary: `${followUp.issueLabel}: the app kept the route open after ${followUp.choiceLabel} instead of ending the flow.`,
        emotional:
          status === "resolved"
            ? "The user marked the route as handled for now."
            : status === "more-guidance"
              ? "The user asked for another layer of guidance."
              : status === "reminder-set"
                ? "The user chose a delayed follow-up instead of forcing an immediate answer."
                : "The route is active and waiting for the next user signal.",
        practical:
          status === "resolved"
            ? "Close the loop and keep the report trail."
            : status === "more-guidance"
              ? "Open AI Guide with the original issue context."
              : status === "reminder-set"
                ? "Return tomorrow and check what changed."
                : "Ask whether the route worked, needs escalation, or needs a reminder.",
        social: `Identity: ${followUp.identityLabel}. Original line: ${followUp.rawText}`,
        safety:
          followUp.route === "urgent" || followUp.choice === "sos"
            ? "Urgent route stayed visible during follow-up."
            : "No new urgent cue was added during this checkpoint.",
        nextStep:
          status === "resolved"
            ? "Keep this route closed unless the issue returns."
            : status === "more-guidance"
              ? "Continue in Guide with the original issue."
              : status === "reminder-set"
                ? "Follow the reminder and reopen Path or Journal."
                : "Choose resolved, more guidance, or reminder.",
        routeLabel: statusLabel,
        identityLabel: followUp.identityLabel,
        issueLabel: followUp.issueLabel,
        entryCount: 0,
        sourceLabel: "Route follow-up",
        dataTrail: [
          `Choice: ${followUp.choiceLabel}`,
          `Status: ${statusLabel}`,
          `Opened: ${followUp.openedAt}`
        ]
      },
      ...current
    ].slice(0, 40));
  }

  function openRouteFollowUp(decision: PendingRouteDecision, choice: RouteChoiceId) {
    if (
      activeRouteFollowUp &&
      activeRouteFollowUp.status === "open" &&
      activeRouteFollowUp.rawText === decision.rawText &&
      activeRouteFollowUp.choice === choice &&
      activeRouteFollowUp.issueId === decision.issueId
    ) {
      return;
    }
    const followUp: ActiveRouteFollowUp = {
      id: `route-follow-up-${Date.now()}`,
      rawText: decision.rawText,
      issueId: decision.issueId,
      issueLabel: decision.issueLabel,
      identityLabel: decision.identityLabel,
      route: decision.route,
      choice,
      choiceLabel: getRouteChoiceLabel(choice),
      openedAt: new Date().toISOString(),
      status: "open"
    };
    setActiveRouteFollowUp(followUp);
  }

  function markRouteFollowUpResolved() {
    const followUp = activeRouteFollowUp;
    if (!followUp) return;
    const nextFollowUp = { ...followUp, status: "resolved" as RouteFollowUpStatus };
    setActiveRouteFollowUp(nextFollowUp);
    writeRouteFollowUpReport(nextFollowUp, "resolved");
    showRouteNotice("Route resolved", "The app closed this loop but kept the report trail.");
  }

  function askMoreRouteGuidance() {
    const followUp = activeRouteFollowUp;
    if (!followUp) return;
    const nextFollowUp = { ...followUp, status: "more-guidance" as RouteFollowUpStatus };
    setActiveRouteFollowUp(nextFollowUp);
    writeRouteFollowUpReport(nextFollowUp, "more-guidance");
    startAIHelpFlow(`Follow up on this issue: ${followUp.rawText}`, followUp.issueId);
  }

  function remindRouteFollowUpTomorrow() {
    const followUp = activeRouteFollowUp;
    if (!followUp) return;
    const nextFollowUp = { ...followUp, status: "reminder-set" as RouteFollowUpStatus };
    setActiveRouteFollowUp(nextFollowUp);
    setIssueGuideId(followUp.issueId);
    writeRouteFollowUpReport(nextFollowUp, "reminder-set");
    void scheduleIssueReminder("tomorrow", followUp.issueId);
    showRouteNotice("Reminder requested", "The follow-up loop will come back tomorrow if notifications are allowed.");
  }

  function commitRouteDecision(choice: RouteChoiceId) {
    const decision = pendingRouteDecision;
    if (!decision) return;

    setPendingRouteDecision(null);
    setHomeIssueDraft("");
    setIssueGuideId(decision.issueId);
    openRouteFollowUp(decision, choice);

    if (choice === "sos") {
      void handleEmergencyCall();
      return;
    }

    if (choice === "help") {
      openRedressTab(decision.redressRouteId);
      return;
    }

    if (choice === "path") {
      startAIHelpFlow(decision.rawText, decision.issueId);
      return;
    }

    if (choice === "reset") {
      openCalmRoute(decision.issueId);
      return;
    }

    if (choice === "search") {
      handleTabPress("search");
      return;
    }

    handleTabPress("journal");
  }

  function startAIHelpFlow(prompt?: string, issueOverride?: IssueId) {
    handleTabPress("aihelp");
    void submitAIHelpText(prompt, issueOverride);
  }

  function routeHomeIssue() {
    const text = homeIssueDraft.trim();
    const routeText = text.length > 0 ? text : `${profileDisplayName} ${selectedIssueGuide.label}`;
    const inferredIdentity = inferIdentityIdFromText(routeText, selectedIdentity.id);
    const inferredIdentityLabel = getIdentityLabel(inferredIdentity);
    if (inferredIdentity !== selectedIdentity.id) {
      setIdentityId(inferredIdentity);
      setProfileRoleId(inferredIdentity);
      setIssueGuideId(getDefaultIssueForIdentity(inferredIdentity));
      setRedressRouteId(getDefaultRedressRouteForIdentity(inferredIdentity));
    }
    const route = detectAIHelpRouteFromText(routeText);
    const issue = findAIHelpIssue(routeText);
    const issueDisplayLabel = issue.id === "anxiety" ? "Calm route" : issue.label;
    const routeLabel =
      route === "redress" || route === "urgent"
        ? "Help"
        : route === "professional"
          ? "Guidance"
          : calmIssueIds.has(issue.id)
            ? "Reset"
            : "Path";
    const nextRedressRouteId = route === "urgent" ? "crime" : findAIHelpRedressRouteFromText(routeText);

    // Build a personal acknowledgment of what was shared — shown BEFORE routing
    const counseling = buildCounselingAcknowledgment(routeText, issue.id, route);
    const detectedDimensions = detectThemes(routeText);

    setVisitReports((current) => [
      {
        id: `home-${Date.now()}`,
        createdAt: new Date().toISOString(),
        kind: "step" as VisitReportKind,
        title: `Heard / ${inferredIdentityLabel}`,
        summary: counseling.heard,
        emotional: counseling.nextStep,
        practical: `Identity: ${inferredIdentityLabel} · Issue: ${issueDisplayLabel}`,
        social: "Your situation was heard. The next step below is matched to what you shared.",
        safety: route === "urgent" ? "Urgent cue detected — safety path is open." : "No emergency signals detected.",
        nextStep: counseling.nextStep,
        routeLabel,
        identityLabel: inferredIdentityLabel,
        issueLabel: issueDisplayLabel,
        entryCount: 0,
        sourceLabel: "Home intake"
      },
      ...current
    ].slice(0, 40));
    setHomeIssueDraft("");
    setHasSubmittedIssue(true);
    setIssueGuideId(issue.id);
    // Log issue detection for exit report
    logSessionEvent({ type: "issue_detected", label: issue.id, detail: issue.label, ts: Date.now() });

    // Show the acknowledgment notice for 3 seconds, then route
    showRouteNotice("Heard", counseling.heard.slice(0, 120) + (counseling.heard.length > 120 ? "…" : ""));

    if (route === "urgent") {
      openRedressTab(nextRedressRouteId);
      return;
    }
    if (route === "redress") {
      // Small delay so the acknowledgment notice is actually read
      setTimeout(() => openRedressTab(nextRedressRouteId), 600);
      return;
    }
    // Any typed life issue should be heard first, then routed through the app.
    const shouldCounselFirst =
      text.length > 0 &&
      (route === "professional" || issue.id !== "general" || detectedDimensions.length > 0);
    if (shouldCounselFirst) {
      setCounselingInitialText(routeText);
      setTimeout(() => {
        setIssueGuideId(issue.id);
        setShowCounselingChat(true);
      }, 700);
      return;
    }
    if (text.length === 0 && calmIssueIds.has(issue.id)) {
      setTimeout(() => openCalmRoute(issue.id), 600);
      return;
    }
    setTimeout(() => startAIHelpFlow(routeText, issue.id), 600);
  }

  function handleJourneyReady(session: CounselingSession) {
    setShowCounselingChat(false);
    setActiveJourney(session);
    setJourneyStepIndex(0);
    // Log counseling completion for exit report
    const turnCount = session.turns?.length ?? 0;
    for (let i = 0; i < Math.max(1, turnCount); i++) {
      logSessionEvent({ type: "counseling_turn", label: session.originalIssue?.slice(0, 60) ?? "Counseling session", ts: Date.now() });
    }
    (session.detectedThemes ?? []).forEach((theme: string) => {
      logSessionEvent({ type: "guidance_viewed", label: theme, ts: Date.now() });
    });
    if (session.journeySteps.length > 0) {
      handleTabPress(session.journeySteps[0].tabId);
    }
  }

  function advanceJourneyStep(skip = false) {
    if (!activeJourney) return;
    const updatedSteps = activeJourney.journeySteps.map((s, i) => {
      if (i === journeyStepIndex) return { ...s, completed: !skip, skipped: skip };
      return s;
    });
    const nextIndex = journeyStepIndex + 1;
    if (nextIndex >= activeJourney.journeySteps.length) {
      // Journey complete — show exit review
      setActiveJourney({ ...activeJourney, journeySteps: updatedSteps, stage: "done" });
      setHasSubmittedIssue(true);
      setShowExitReviewPrompt(true);
      setShowOnboardingPanel(true);
      return;
    }
    const nextStep = updatedSteps[nextIndex];
    setActiveJourney({ ...activeJourney, journeySteps: updatedSteps });
    setJourneyStepIndex(nextIndex);
    handleTabPress(nextStep.tabId);
  }

  function endJourney() {
    setActiveJourney(null);
    setJourneyStepIndex(0);
    setHasSubmittedIssue(true);
    setShowExitReviewPrompt(true);
    setShowOnboardingPanel(true);
  }

  function buildNearbySearchUrl(query: string) {
    const locality = supportLocality.trim();
    const area = locality.length > 0 ? locality : "your area";
    return `https://www.google.com/maps/search/${encodeURIComponent(`${query} near ${area}`)}`;
  }

  function getNearbySearchQuery(resourceId: string) {
    if (resourceId === "hpr") return "psychologist counselor psychiatrist doctor";
    if (resourceId === "hfr") return "clinic hospital doctor";
    if (resourceId === "esanjeevani") return "doctor telemedicine";
    return "mental health counselor psychologist";
  }

  function getRecommendedCarePaths(identity: IdentityId): CarePath[] {
    if (identity === "student" || identity === "child") {
      return [
        { id: "student-counselor", label: "Counselor", detail: "Good first step for stress, school pressure, and talking things through.", query: "counselor" },
        { id: "student-psychologist", label: "Psychologist", detail: "Useful for patterns, coping skills, and structured support.", query: "psychologist" },
        { id: "student-doctor", label: "Doctor", detail: "Helpful when sleep, energy, appetite, or body symptoms are involved.", query: "doctor" }
      ];
    }

    if (identity === "parent" || identity === "caregiver") {
      return [
        { id: "caregiver-counselor", label: "Counselor", detail: "Helpful when the load is emotional or you need a steady place to talk.", query: "counselor" },
        { id: "caregiver-doctor", label: "Doctor", detail: "Good for stress that is affecting the body or sleep.", query: "doctor" },
        { id: "caregiver-psychiatrist", label: "Psychiatrist", detail: "Use when symptoms feel intense, persistent, or need medical review.", query: "psychiatrist" }
      ];
    }

    if (identity === "officer" || identity === "official") {
      return [
        { id: "duty-psychologist", label: "Psychologist", detail: "Useful for decompression, pattern review, and work stress processing.", query: "psychologist" },
        { id: "duty-psychiatrist", label: "Psychiatrist", detail: "Helpful if sleep, anxiety, or mood symptoms need clinical support.", query: "psychiatrist" },
        { id: "duty-doctor", label: "Doctor", detail: "A sound first stop when stress is showing up physically.", query: "doctor" }
      ];
    }

    if (identity === "professional" || identity === "teacher" || identity === "retired") {
      return [
        { id: "adult-psychologist", label: "Psychologist", detail: "Best for reflection, habits, and making sense of a full mind.", query: "psychologist" },
        { id: "adult-counselor", label: "Counselor", detail: "Useful for a human conversation and short-term support.", query: "counselor" },
        { id: "adult-doctor", label: "Doctor", detail: "Good if the body, sleep, or concentration is getting affected.", query: "doctor" }
      ];
    }

    return [
      { id: "general-counselor", label: "Counselor", detail: "A gentle place to start when you want to talk it out.", query: "counselor" },
      { id: "general-psychologist", label: "Psychologist", detail: "Useful for deeper patterns and coping tools.", query: "psychologist" },
      { id: "general-doctor", label: "Doctor", detail: "Good when symptoms are physical, persistent, or unclear.", query: "doctor" }
    ];
  }

function isIssueId(value: string): value is IssueId {
    return (
      value === "general" ||
      value === "anger" ||
      value === "anxiety" ||
      value === "fear" ||
      value === "overconfidence" ||
      value === "stigma" ||
      value === "burnout" ||
      value === "loneliness"
    );
  }

function isIssueReminderMode(value: string): value is IssueReminderMode {
  return value === "tomorrow" || value === "week";
}

function isRedressRouteId(value: string): value is RedressRouteId {
  return (
    value === "academic" ||
    value === "harassment" ||
    value === "ragging" ||
    value === "public" ||
    value === "private" ||
    value === "crime" ||
    value === "financial" ||
    value === "domestic" ||
    value === "workplace"
  );
}

function isInstitutionSectorId(value: string): value is InstitutionSectorId {
  return (
    value === "university" ||
    value === "iit" ||
    value === "medical" ||
    value === "law" ||
    value === "school" ||
    value === "banking" ||
    value === "government" ||
    value === "private" ||
    value === "factory"
  );
}

